import logging
import time

from ute_common_abstract_core.exceptions import ConfigurationNotDefined
from ute_ue.config import loggers as ute_ue_logging
from ute_ue.exceptions import RequiredUeNotFound
from ute_ue.exceptions import UeCommunicationError
from ute_ue.exceptions import UnknownUe
from ute_ue.lteuepool import CfgFileBasedUePool
from ta_ue_plugin_ultracaller.uc_connection import UcConnection
from ta_ue_plugin_ultracaller.uc_ue import UcUe


class UcUes(object):
    """UltraCaller ue inventory"""
    def __init__(self):
        """Basic initialization."""
        self.available = []
        self.reserved = []
        self.dead = []


class UltraCallerUePool(CfgFileBasedUePool):
    """UltraCaller Ue Pool"""

    # required keys in configuration dictionary
    REQUIRED_CONFIGURATION = ['server_address', 'token', 'ue_group']
    DEFAULT_UE_ALIVE_TIMEOUT = 60  # Default UE alive timeout is used if the value is not available in configuration

    def __init__(self, configuration):
        """Basic initialization."""
        super(UltraCallerUePool, self).__init__()
        raw_logger = logging.getLogger("ute_ue")
        self.logger = ute_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UEPOOL'})
        self.logger.info('UltraCaller UE pool created with configuration: \n {}'.format(configuration))

        self._configuration = configuration
        self._check_required_configuration(configuration)
        self._check_optional_configuration(configuration)

        self._reserved_ues = set()  # set of ue imeis that are currently reserved

        self._uc_connection = UcConnection(self._configuration)

        self.ues = self._get_ues()
        self._check_available_ues(self.ues)

    def get_ue(self, ue_characteristics):
        """
        Return LteUe instance fulfilling requirements. (public API)

        :return: ue instance
        :raises: :py:class:`ute_ue.exceptions.RequiredUeNotFound`: If matching ue is not found
        """
        for ue in self.ues.available:
            if ue['imei'] in self._reserved_ues:
                self.logger.debug('Ue {} already reserved skipping.'.format(ue['imei']))
                continue

            # If there is requested cell ue must be connected to it
            if ue_characteristics.starting_cell:
                try:
                    if str(ue_characteristics.starting_cell) != ue['location']['signalInfo']['CID']:
                        self.logger.debug('Ue {} is connected to wrong cell'.format(ue['imei']))
                        continue
                except KeyError:
                    self.logger.debug('Ue {} does not have signalInfo and there is requested cell'.format(ue['imei']))
                    continue

            # Ue must have an imei
            if not ue['imei']:
                self.logger.warning('Ultracaller ue is missing imei\n{}'.format(ue))
                continue

            # If domain capabilities are given ue must match those
            if not self._match_domain_capabilities(ue_characteristics.domain_capabilities, ue):
                self.logger.debug('Ue {} does not match domain capabilities: {}'.format(ue['imei'], ue_characteristics.domain_capabilities))
                continue

            ue_obj = self._create_ue(ue)
            self._reserved_ues.add(ue['imei'])
            self.logger.info('UltraCallerUePool UE reserved with imei: {}'.format(ue['imei']))
            return ue_obj

        raise RequiredUeNotFound('UE that matches requirements: {} is not found'.format(ue_characteristics))

    def _match_domain_capabilities(self, domain_capabilities, ue):
        if isinstance(domain_capabilities, dict):
            imei = domain_capabilities.get('imei', None)
            imsi = domain_capabilities.get('imsi', None)
            manufacturer = domain_capabilities.get('manufacturer', None)
            model = domain_capabilities.get('model', None)
            device_name = domain_capabilities.get('device_name', None)

            if imei and str(imei) != ue['imei']:
                return False
            if imsi and str(imsi) != ue['imsi']:
                return False
            if manufacturer and manufacturer != ue['deviceManu']:
                return False
            if model and model != ue['deviceModel']:
                return False
            if device_name and device_name != ue['clientName']:
                return False
            # All given values match
            return True
        else:
            self.logger.debug('No valid domain capabilities provided. Domain capability will be ignored.')
            return True

    def _get_device(self, ue_characteristics):
        return self.get_ue(ue_characteristics)

    def release_ue(self, ue):
        """
        Allow UE to be reused - it should be in pool of available UEs. (public API)

        :raises: :py:class:`ute_ue.exceptions.UnknownUe`: If given ue has not been returned from this pool via get_ue()
        :return: None
        """
        try:
            imei = ue.get_imei()
            self._reserved_ues.remove(imei)
            ue.shutdown()
        except (KeyError, AttributeError):
            raise UnknownUe('UE: {} is not reserved from UltraCallerUePool'.format(ue))

        self.logger.info('UltraCallerUePool UE released with imei: {}'.format(imei))

    def _release_device(self, ue):
        return self.release_ue(ue)

    def shutdown(self):
        """Release all resources used by this pool and UEs in this pool."""
        self._reserved_ues = set()

    def _get_ues(self):
        """
        Fetch ues from requested group from UC server and sort ues to available, reserved and dead
        :return: UcUes object
        """
        ue_data = UcUes()

        head_group = self._configuration['ue_group']
        sub_group = self._configuration.get('sub_group', None)
        response = self._uc_connection.search_ues_by_group(head_group=head_group, sub_group=sub_group)

        for ue in response['data']:
            last_seen = time.time() - ue['lastSeen'] / 1000
            if ue['imei'] in self._reserved_ues:
                ue_data.reserved.append(ue)
            elif last_seen <= self._configuration['ue_alive_timeout']:
                ue_data.available.append(ue)
            else:
                ue_data.dead.append(ue)
        return ue_data

    def _create_ue(self, ue):
        """
        Create UcUe object
        :param ue: Ue dictionary from UC
        :return: UcUe object
        """
        name = '{}'.format(ue['imei'])
        conf = {'imei': ue['imei'],
                'uc_connection': self._uc_connection,
                'ue_alive_timeout': self._configuration['ue_alive_timeout'],
                'ue_info': ue,
                'APP_SERVERS': self._configuration.get('APP_SERVERS')}
        return UcUe(name, configuration=conf)

    @staticmethod
    def _check_required_configuration(configuration):
        """
        Check that configuration contains all mandatory parameters
        :param configuration:
        :return None
        :raises: ConfigurationNotDefined if mandatory parameter(s) missing
        """
        missing_config = []
        for key in UltraCallerUePool.REQUIRED_CONFIGURATION:
            if key not in configuration:
                missing_config.append(key)
        if missing_config:
            raise ConfigurationNotDefined('Mandatory configuration missing for UltraCallerUePool: '
                                          '{} '.format(missing_config))

    def _check_optional_configuration(self, configuration):
        """
        Check for optional parameters
        :param configuration:
        :return: None
        """
        if 'ue_alive_timeout' not in configuration:
            self._configuration['ue_alive_timeout'] = UltraCallerUePool.DEFAULT_UE_ALIVE_TIMEOUT

        if 'sub_group' not in configuration:
            self._configuration['sub_group'] = None

        if 'app_servers' not in configuration:
            self._configuration['app_servers'] = None

    def _check_available_ues(self, ues):
        """
        Check that there is at least one ue available
        :return None
        :raises: UeCommunicationError if no ues found or no ues alive
        """
        if len(ues.available) + len(ues.dead) == 0:
            raise UeCommunicationError('No UEs found in testline')
        for ue in ues.dead:
            self.logger.warning('Dead UE in testline imei: {}, last seen: {}s ago'.format(ue['imei'], ue['lastSeen']))
        if not ues.available:
            raise UeCommunicationError('No UEs alive in testline')
